modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.InvertingAmp;
end Baseline;
model BUG006
  extends Modelica.Electrical.Analog.Examples.InvertingAmp(f=0);
end BUG006;
model FinalBUG006
  extends Modelica.Electrical.Analog.Examples.InvertingAmp(final f=0);
end FinalBUG006;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG006\n");
simulate(BUG006, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG006\n");
simulate(FinalBUG006, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG006\n");
system("./Baseline -override f=0 -r=BUG006_override.csv");
